--
-- Name: create_temporal_table(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_temporal_table(target_table text, history_table text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
      DECLARE
        func_name text;
      BEGIN
        func_name := target_table || '_temporal';

        -- Add sys_period column to main table if not exists
        EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS sys_period tstzrange NOT NULL DEFAULT tstzrange(current_timestamp, null)', target_table);

        -- Drop and recreate history table
        -- IMPORTANT: EXCLUDING CONSTRAINTS EXCLUDING INDEXES prevents copying unique indexes!
        EXECUTE format('DROP TABLE IF EXISTS %I CASCADE', history_table);
        EXECUTE format('CREATE TABLE %I (LIKE %I INCLUDING DEFAULTS EXCLUDING CONSTRAINTS EXCLUDING INDEXES)', history_table, target_table);

        -- Add only the indexes we want (all non-unique for history tables)
        EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (id, sys_period)',
                       history_table || '_id_period_idx', history_table);

        -- Create the temporal trigger function
        EXECUTE format('
          CREATE OR REPLACE FUNCTION %I()
          RETURNS TRIGGER AS $func$
          BEGIN
            IF TG_OP = ''DELETE'' THEN
              OLD.sys_period := tstzrange(lower(OLD.sys_period), current_timestamp);
              RETURN OLD;
            ELSIF TG_OP = ''UPDATE'' THEN
              OLD.sys_period := tstzrange(lower(OLD.sys_period), current_timestamp);
              NEW.sys_period := tstzrange(current_timestamp, null);
              RETURN NEW;
            ELSIF TG_OP = ''INSERT'' THEN
              NEW.sys_period := tstzrange(current_timestamp, null);
              RETURN NEW;
            END IF;
          END;
          $func$ LANGUAGE plpgsql', func_name, history_table, history_table);

        -- Drop and recreate trigger
        EXECUTE format('DROP TRIGGER IF EXISTS temporal_trigger ON %I', target_table);
        EXECUTE format('
          CREATE TRIGGER temporal_trigger
          BEFORE INSERT OR UPDATE OR DELETE ON %I
          FOR EACH ROW EXECUTE FUNCTION %I()', target_table, func_name);
      END;
      $_$;


ALTER FUNCTION public.create_temporal_table(target_table text, history_table text) OWNER TO postgres;

--
-- Name: create_temporal_table_with_schema(text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_temporal_table_with_schema(target_schema text, target_table text, history_schema text, history_table text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
      DECLARE
        qualified_target text;
        qualified_history text;
        func_name text;
      BEGIN
        -- Build qualified names
        qualified_target := format('%I.%I', target_schema, target_table);
        qualified_history := format('%I.%I', history_schema, history_table);

        -- Function name should be schema_table_temporal to avoid conflicts
        func_name := format('%I_%I_temporal', target_schema, target_table);

        -- Add sys_period column to main table if not exists
        EXECUTE format('ALTER TABLE %s ADD COLUMN IF NOT EXISTS sys_period tstzrange NOT NULL DEFAULT tstzrange(current_timestamp, null)', qualified_target);

        -- Drop and recreate history table
        EXECUTE format('DROP TABLE IF EXISTS %s CASCADE', qualified_history);
        EXECUTE format('CREATE TABLE %s (LIKE %s INCLUDING DEFAULTS EXCLUDING CONSTRAINTS EXCLUDING INDEXES)', qualified_history, qualified_target);

        -- Add index on history table
        EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %s (id, sys_period)',
                       format('%s_%s_id_period_idx', history_schema, history_table), qualified_history);

        -- Create the temporal trigger function in the target schema with CORRECT syntax
        EXECUTE format('
          CREATE OR REPLACE FUNCTION %I.%I()
          RETURNS TRIGGER AS $func$
          BEGIN
            IF TG_OP = ''DELETE'' THEN
              -- Close the sys_period and insert OLD record into history
              OLD.sys_period := tstzrange(lower(OLD.sys_period), current_timestamp);
              RETURN OLD;
            ELSIF TG_OP = ''UPDATE'' THEN
              -- Close the sys_period and insert OLD record into history
              OLD.sys_period := tstzrange(lower(OLD.sys_period), current_timestamp);
              -- Set new sys_period for updated record
              NEW.sys_period := tstzrange(current_timestamp, null);
              RETURN NEW;
            ELSIF TG_OP = ''INSERT'' THEN
              -- Set sys_period for new record
              NEW.sys_period := tstzrange(current_timestamp, null);
              RETURN NEW;
            END IF;
          END;
          $func$ LANGUAGE plpgsql', target_schema, func_name, qualified_history, qualified_history);

        -- Drop and recreate trigger
        EXECUTE format('DROP TRIGGER IF EXISTS temporal_trigger ON %s', qualified_target);
        EXECUTE format('
          CREATE TRIGGER temporal_trigger
          BEFORE INSERT OR UPDATE OR DELETE ON %s
          FOR EACH ROW EXECUTE FUNCTION %I.%I()', qualified_target, target_schema, func_name);
      END;
      $_$;


ALTER FUNCTION public.create_temporal_table_with_schema(target_schema text, target_table text, history_schema text, history_table text) OWNER TO postgres;

