    LANGUAGE plpgsql
    AS $$
      BEGIN
        IF (TG_OP = 'DELETE') THEN
            user_journey_transition_id, user_journey_id, to_state, metadata,
            sort_key, most_recent, created_at, updated_at, sys_period
          )
          SELECT
            OLD.id, OLD.user_journey_id, OLD.to_state, OLD.metadata,
            OLD.sort_key, OLD.most_recent, OLD.created_at, OLD.updated_at,
            tstzrange(OLD.updated_at, CURRENT_TIMESTAMP);
          RETURN OLD;
        ELSIF (TG_OP = 'UPDATE') THEN
            user_journey_transition_id, user_journey_id, to_state, metadata,
            sort_key, most_recent, created_at, updated_at, sys_period
          )
          SELECT
            OLD.id, OLD.user_journey_id, OLD.to_state, OLD.metadata,
            OLD.sort_key, OLD.most_recent, OLD.created_at, OLD.updated_at,
            tstzrange(OLD.updated_at, CURRENT_TIMESTAMP);
          RETURN NEW;
        END IF;
        RETURN NULL;
      END;
      $$;


