-- Name: status_codes_temporal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.status_codes_temporal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
          BEGIN
            IF TG_OP = 'DELETE' THEN
              -- Modify sys_period BEFORE inserting
              OLD.sys_period := tstzrange(lower(OLD.sys_period), current_timestamp);
              RETURN OLD;
            ELSIF TG_OP = 'UPDATE' THEN
              -- Always record history on UPDATE (no comparison check)
              OLD.sys_period := tstzrange(lower(OLD.sys_period), current_timestamp);
              -- Update sys_period for new version
              NEW.sys_period := tstzrange(current_timestamp, null);
              RETURN NEW;
            ELSIF TG_OP = 'INSERT' THEN
              -- Set sys_period for new records
              NEW.sys_period := tstzrange(current_timestamp, null);
              RETURN NEW;
            END IF;
          END;
          $$;


ALTER FUNCTION public.status_codes_temporal() OWNER TO postgres;

